-- IMPORTAÇÃO DE CONTATOS - GAVINACAO
-- Rode este script no SQL Editor do Supabase
-- ==========================================================

DO $import_script$
DECLARE
  v_company_id uuid;
BEGIN
  -- Pega a empresa do Gavinacao
  SELECT company_id INTO v_company_id FROM public.users WHERE email = 'gavinacao@gmail.com' LIMIT 1;

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Empresa do Gavinacao nao encontrada!';
  END IF;

Casa Vidro Esquadrias Especiais Ltda', 'Obs: VEIO DO ANUNCIO BANCADA') ON CONFLICT (company_id, phone) DO UPDATE SET notes = EXCLUDED.notes, name = EXCLUDED.name;
END $import_script$;
